_categories = None
_db = None


def getdb():
    global _db
    if _db is None:
        _db = web.database(**config.db_parameters)
    return _db


def get_category_id(category):
    global _categories
    if _categories is None:
        _categories = {}
        for c in getdb().select('category'):
            _categories[c.name] = c.id
    return _categories.get(category)


def new(
    category,
    olid,
    filename,
    filename_s,
    filename_m,
    filename_l,
    author,
    ip,
    source_url,
    width,
    height,
):
    category_id = get_category_id(category)
    now = datetime.datetime.utcnow()

    db = getdb()

    t = db.transaction()
    try:
        cover_id = db.insert(
            'cover',
            category_id=category_id,
            filename=filename,
            filename_s=filename_s,
            filename_m=filename_m,
            filename_l=filename_l,
            olid=olid,
            author=author,
            ip=ip,
            source_url=source_url,
            width=width,
            height=height,
            created=now,
            last_modified=now,
            deleted=False,
            archived=False,
        )

        db.insert("log", action="new", timestamp=now, cover_id=cover_id)
    except:
        t.rollback()
        raise
    else:
        t.commit()
    return cover_id


def query(category, olid, offset=0, limit=10):
    category_id = get_category_id(category)
    deleted = False

    if isinstance(olid, list):
        if len(olid) == 0:
            olid = [-1]
        where = web.reparam(
            'deleted=$deleted AND category_id = $category_id AND olid IN $olid',
            locals(),
        )
    elif olid is None:
        where = web.reparam('deleted=$deleted AND category_id=$category_id', locals())
    else:
        where = web.reparam(
            'deleted=$deleted AND category_id=$category_id AND olid=$olid', locals()
        )

    result = getdb().select(
        'cover',
        what='*',
        where=where,
        order='last_modified desc',
        offset=offset,
        limit=limit,
    )
    return result.list()


